relevant_functions.make_user_text:
def make_user_text(features):
    lines = ['Data survei kesehatan (kode fitur mengikuti UCI):']
    for name in FEATURES:
        value = float(features[name])
        value = int(value) if value.is_integer() else value
        lines.append(f'{name}: {value}')
    lines.append('Label Diabetes_binary (0 atau 1):')
    return '\n'.join(lines)

relevant_functions.prompt_ids:
def prompt_ids(features):
    messages = [{'role': 'system', 'content': SYSTEM_PROMPT}, {'role': 'user', 'content': make_user_text(features)}]
    return tokenizer.apply_chat_template(messages, tokenize=True, add_generation_prompt=True)

relevant_functions.encode_training_row:
def encode_training_row(row):
    prefix = prompt_ids(row)
    answer = [LABEL_TOKEN_IDS[int(row['target'])], EOT_ID]
    assert len(prefix) + len(answer) <= MAX_LENGTH, f'Input terlalu panjang ({len(prefix)}). Naikkan MAX_LENGTH dengan memperhatikan VRAM.'
    ids = prefix + answer
    return {'input_ids': ids, 'attention_mask': [1] * len(ids), 'labels': [-100] * len(prefix) + answer}
